g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "x": 72,
  "y": 200,
  "width": 1136,
  "height": 400,
  "name": "penalty-matrix",
  "column_widths": [
    220,
    316,
    300,
    300
  ],
  "row_heights": [
    40,
    120,
    120,
    120
  ],
  "style": {
    "font_size": 18,
    "header_fill": "#1F2A37",
    "header_text": "#F7F4EE",
    "body_text": "#232A31",
    "band_row": false
  },
  "defaults": {
    "cell": {
      "font_size": 18,
      "align": "l",
      "valign": "middle",
      "padding": 14,
      "borders": {
        "bottom": {
          "style": "solid",
          "color": "#E4DED3",
          "width": 1
        }
      }
    }
  },
  "columns": [
    {
      "text": "法律与条款",
      "bold": true,
      "align": "l",
      "borders": {
        "bottom": {
          "style": "solid",
          "color": "#1F2A37",
          "width": 2
        }
      }
    },
    {
      "text": "一般情形",
      "bold": true,
      "align": "l",
      "borders": {
        "bottom": {
          "style": "solid",
          "color": "#1F2A37",
          "width": 2
        }
      }
    },
    {
      "text": "严重情形",
      "bold": true,
      "align": "l",
      "borders": {
        "bottom": {
          "style": "solid",
          "color": "#1F2A37",
          "width": 2
        }
      }
    },
    {
      "text": "附加后果",
      "bold": true,
      "align": "l",
      "borders": {
        "bottom": {
          "style": "solid",
          "color": "#1F2A37",
          "width": 2
        }
      }
    }
  ],
  "rows": [
    [
      {
        "text": "《网络安全法》第六十一条",
        "bold": true
      },
      {
        "text": "单位 1 万–5 万元；拒不改正或致危害后果5 万–50 万元；直接责任人员 1 万–10 万元"
      },
      {
        "text": "严重后果：单位 50 万–200万元，个人 5 万–20 万元；特别严重：单位 200 万–1000 万元，个人 20 万–100 万元"
      },
      {
        "text": "第六十六条第三款：受治安管理处罚的五年内、受刑事处罚的终身，不得从事网络安全管理和网络运营关键岗位",
        "color": "#C0392B"
      }
    ],
    [
      {
        "text": "《数据安全法》第四十五条",
        "bold": true
      },
      {
        "text": "单位 5 万–50 万元；直接责任人员 1 万–10 万元"
      },
      {
        "text": "单位 50 万–200 万元；直接责任人员 5 万–20 万元"
      },
      {
        "text": "可责令停业整顿、吊销许可或营业执照",
        "color": "#C0392B"
      }
    ],
    [
      {
        "text": "《个人信息保护法》第六十六条",
        "bold": true,
        "borders": {
          "bottom": {
            "style": "solid",
            "color": "#1F2A37",
            "width": 2
          }
        }
      },
      {
        "text": "拒不改正并处 100 万元以下；直接责任人员 1 万–10 万元",
        "borders": {
          "bottom": {
            "style": "solid",
            "color": "#1F2A37",
            "width": 2
          }
        }
      },
      {
        "text": "5000 万元以下或上一年度营业额 5% 以下；直接责任人员 10 万–100 万元",
        "borders": {
          "bottom": {
            "style": "solid",
            "color": "#1F2A37",
            "width": 2
          }
        }
      },
      {
        "text": "可禁止其在一定期限内担任董事、监事、高管和个人信息保护负责人",
        "color": "#C0392B",
        "borders": {
          "bottom": {
            "style": "solid",
            "color": "#1F2A37",
            "width": 2
          }
        }
      }
    ]
  ]
}
